"""Keyed totals: sum values by key and answer queries.

Usage: main.py <input-file>

The input is processed as raw bytes so that keys compare by their exact bytes
(no Unicode normalisation or decoding errors) and are echoed back unchanged.
"""

import sys

INT64_MIN = -(2**63)
INT64_MAX = 2**63 - 1

OVERFLOW = object()


def split_lines(data: bytes) -> list[bytes]:
    """Split into lines on LF, tolerating CRLF and a missing final newline."""
    if data.startswith(b"\xef\xbb\xbf"):
        data = data[3:]
    if not data:
        return []
    lines = data.split(b"\n")
    if lines[-1] == b"":
        lines.pop()
    return [line[:-1] if line.endswith(b"\r") else line for line in lines]


def parse_value(token: bytes) -> int:
    digits = token[1:] if token.startswith(b"-") else token
    if not digits or not digits.isdigit():
        raise ValueError(f"invalid value: {token!r}")
    return int(token)


def compute(data: bytes) -> bytes:
    lines = split_lines(data)

    totals: dict[bytes, object] = {}
    i = 0
    while i < len(lines) and lines[i].strip(b" ") != b"":
        fields = [f for f in lines[i].split(b" ") if f]
        i += 1
        if len(fields) != 2:
            raise ValueError(f"malformed record on line {i}: {lines[i - 1]!r}")
        key, value = fields[0], parse_value(fields[1])
        current = totals.get(key, 0)
        if current is OVERFLOW:
            continue
        total = current + value
        totals[key] = total if INT64_MIN <= total <= INT64_MAX else OVERFLOW

    out = []
    for line in lines[i + 1 :]:
        key = line.strip(b" ")
        if not key:
            continue
        total = totals.get(key)
        if total is None:
            answer = b"absent"
        elif total is OVERFLOW:
            answer = b"overflow"
        else:
            answer = str(total).encode("ascii")
        out.append(key + b"=" + answer + b"\n")
    return b"".join(out)


def main(argv: list[str]) -> int:
    if len(argv) < 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2
    with open(argv[1], "rb") as f:
        data = f.read()
    sys.stdout.buffer.write(compute(data))
    sys.stdout.buffer.flush()
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

